#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs;
using MVZ2.GameContent.Buffs.SeedPacks;
using MVZ2.Vanilla.Artifacts;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Properties;
using MVZ2Logic;
using MVZ2Logic.Artifacts;
using MVZ2Logic.Definitions;
using MVZ2Logic.Level;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.SeedPacks;
using PVZEngine.Tools;

namespace MVZ2.GameContent.Artifacts
{
    [AutoArtifactDefinition(VanillaArtifactNames.bunbunmaruNewspaper)]
    public class BunbunmaruNewspaper : ArtifactDefinition
    {
        public BunbunmaruNewspaper(string nsp, string name) : base(nsp, name)
        {
            AddAura(new BlueprintAura());
        }
        public override void PostAdd(Artifact artifact)
        {
            base.PostAdd(artifact);
            artifact.SetNumber(GetMaxCooldownSeconds(artifact));
        }
        public override void PostUpdate(Artifact artifact)
        {
            base.PostUpdate(artifact);

            if (artifact.RunAndPassedOneSecond())
            {
                var number = artifact.GetNumber();
                number--;
                if (number <= 0)
                {
                    number = GetMaxCooldownSeconds(artifact);
                    var aura = artifact.GetAuraEffect<BlueprintAura>();
                    if (aura != null)
                    {
                        aura.UpdateAura();
                        artifact.Highlight();
                        artifact.Level.PlaySound(VanillaSoundID.confusionShimmer);
                    }
                }
                artifact.SetNumber(number);
            }
        }
        public static int GetMaxCooldownSeconds(Artifact artifact) => artifact.GetProperty<int>(PROP_MAX_COOLDOWN_SECONDS);
        public static void SetMaxCooldownSeconds(Artifact artifact, int value) => artifact.SetProperty(PROP_MAX_COOLDOWN_SECONDS, value);
        public static int GetMinCostSteps(Artifact artifact) => artifact.GetProperty<int>(PROP_MIN_COST_STEPS);
        public static void SetMinCostSteps(Artifact artifact, int value) => artifact.SetProperty(PROP_MIN_COST_STEPS, value);
        public static int GetMaxCostSteps(Artifact artifact) => artifact.GetProperty<int>(PROP_MAX_COST_STEPS);
        public static void SetMaxCostSteps(Artifact artifact, int value) => artifact.SetProperty(PROP_MAX_COST_STEPS, value);
        public static int GetCostStep(Artifact artifact) => artifact.GetProperty<int>(PROP_COST_STEP);
        public static void SetCostStep(Artifact artifact, int value) => artifact.SetProperty(PROP_COST_STEP, value);
        public static readonly VanillaArtifactPropertyMeta<int> PROP_MAX_COOLDOWN_SECONDS = new VanillaArtifactPropertyMeta<int>("max_cooldown_seconds", 30);
        public static readonly VanillaArtifactPropertyMeta<int> PROP_MIN_COST_STEPS = new VanillaArtifactPropertyMeta<int>("min_cost_steps", 0);
        public static readonly VanillaArtifactPropertyMeta<int> PROP_MAX_COST_STEPS = new VanillaArtifactPropertyMeta<int>("max_cost_steps", 12);
        public static readonly VanillaArtifactPropertyMeta<int> PROP_COST_STEP = new VanillaArtifactPropertyMeta<int>("cost_step", 25);
        public class BlueprintAura : AuraEffectDefinition
        {
            public BlueprintAura() : base(VanillaBuffID.SeedPack.bunbunmaruNewspaper, 0)
            {
            }
            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var level = auraEffect.Source.GetLevel();
                using var seedPacksItem = level.GetAllSeedPacksDisposeable();
                foreach (var seed in seedPacksItem.Value)
                {
                    if (seed == null)
                        continue;
                    results.Add(seed);
                }
            }
            public override void UpdateTargetBuff(AuraEffect effect, IBuffTarget target, Buff buff)
            {
                base.UpdateTargetBuff(effect, target, buff);
                var source = effect.Source as Artifact;
                if (source == null)
                    return;
                var rng = source.RNG;
                var minSteps = GetMinCostSteps(source);
                var maxSteps = GetMaxCostSteps(source);
                var step = GetCostStep(source);
                var cost = rng.Next(minSteps, maxSteps + 1) * step;
                BunbunmaruNewspaperBuff.SetCost(buff, cost);
            }
        }
    }
}
